-- 8회차 1: 국내 최신 리스크 팩터가 쓴 창(3Y/1Y)별 종목 수와 리스크 점수 표준편차 (docs/factors.md 12.10). db-status.yml sql 입력으로(주석 줄 빼고)
WITH d AS (SELECT MAX(f.as_of_date) AS d FROM factors f JOIN stocks s ON s.id = f.stock_id WHERE s.country = 'KR' AND f.factor = 'risk'), x AS (SELECT COALESCE(json_extract(f.raw_json, '$._metrics_source.window'), '?') AS win, f.score FROM factors f JOIN stocks s ON s.id = f.stock_id WHERE s.country = 'KR' AND f.factor = 'risk' AND f.as_of_date = (SELECT d FROM d) AND f.score IS NOT NULL) SELECT (SELECT d FROM d) AS as_of, win, COUNT(*) AS n, ROUND(AVG(score), 1) AS avg, ROUND(SQRT(AVG(score * score) - AVG(score) * AVG(score)), 1) AS sd FROM x GROUP BY win
